```cpp
#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> fact(n, 1);
        for (int i = 1; i < n; ++i) {
            fact[i] = fact[i - 1] * i;
        }

        vector<int> nums;
        for (int i = 1; i <= n; ++i) nums.push_back(i);

        --k;
        string result;

        for (int remaining = n; remaining > 0; --remaining) {
            int blockSize = fact[remaining - 1];
            int index = k / blockSize;
            result += to_string(nums[index]);
            nums.erase(nums.begin() + index);
            k %= blockSize;
        }

        return result;
    }
};
```

