#include <string>
#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    string getPermutation(int n, int k) {
        --k;  // 转为 0-based
        vector<int> nums(n);
        iota(nums.begin(), nums.end(), 1);

        vector<int> fact(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            fact[i] = fact[i - 1] * i;
        }

        string result;
        for (int i = n - 1; i >= 0; --i) {
            int index = k / fact[i];
            result += to_string(nums[index]);
            nums.erase(nums.begin() + index);
            k %= fact[i];
        }
        return result;
    }
};
```

