```cpp
#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> fact(n, 1);
        for (int i = 1; i < n; ++i) {
            fact[i] = fact[i - 1] * i;
        }

        vector<int> nums;
        for (int i = 1; i <= n; ++i) nums.push_back(i);

        --k;
        string result;

        for (int remaining = n; remaining > 0; --remaining) {
            int blockSize = fact[remaining - 1];
            int index = k / blockSize;
            result += to_string(nums[index]);
            nums.erase(nums.begin() + index);
            k %= blockSize;
        }

        return result;
    }
};
```

两份回答的核心算法都正确，且都正确处理了题目给定的 `n <= 9` 范围。Assistant A 的阶乘数组和索引计算正确，代码也能通过示例；额外附带的 `main` 测试代码虽非必要，但不影响正确性。

